test_that("table_layout_cell_paragraphs_stay_separated: Adjacent paragraphs in a layout-table cell are separated rather than concatenated into one run of text", {
  result <- convert(html = "<table><tr><td><p><b>Alice Example</b></p><p><i>Customer Service</i></p></td><td>Logo</td></tr><tr><td>A</td><td>B</td><td>C</td></tr></table>", options = ConversionOptions$from_json(jsonlite::toJSON(list("compact_tables" = TRUE), auto_unbox = TRUE)))
  expect_false(grepl("**Alice Example***Customer Service*", result$content, fixed = TRUE))
  expect_true(any(grepl("Alice Example", result$content, fixed = TRUE)))
  expect_true(any(grepl("Customer Service", result$content, fixed = TRUE)))
  expect_true(any(grepl("Logo", result$content, fixed = TRUE)))
})

test_that("table_layout_row_keeps_image: A layout-table row keeps an image as Markdown instead of degrading it to alt text", {
